insert into public.recipes (
  owner_id, slug, name, description, servings, prep_minutes, cook_minutes, total_minutes,
  category, tags, image_path, based_on, notes
) values
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'avgolemono-lobster-mushroom-soup', 'Avgolemono (Greek Lemon Rice Soup) with Lobster Mushroom', 'Silky egg-lemon broth with tender arborio rice and seared lobster mushroom.', 2, 15, 30, 45,
   'Soup', array['soup', 'mushroom']::text[], null, 'Claude', array['Never let the soup boil after adding the egg mixture, or it will curdle.', 'It thickens as it sits, so thin leftovers with a splash of warm stock and reheat gently over low heat.', 'Seafood stock brings out the mushroom''s seafood-like flavor.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'chanterelle-cream-linguine', 'Chanterelle Cream Linguine', 'Golden chanterelles and shallot in a silky parmesan cream sauce over linguine.', 2, 10, 20, 30,
   'Pasta', array['pasta', 'mushroom']::text[], null, 'Claude', array['Chanterelles hold a lot of water, so the dry-sauté step is what gives you good flavor and texture instead of steamed mushrooms. Brush them clean rather than soaking.', 'For a bit of heat, add a splash of Worcestershire with the wine and finish with a pinch of cayenne.', 'To add protein, toss in seared shrimp or crisp bacon at the end. A squeeze of lemon at the table brightens the cream.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'chocolate-chip-pecan-blondies', 'Chocolate Chip Pecan Blondies', 'Chewy, buttery blondies with toasted pecans and chocolate chips, baked in a 9x12 pan.', 12, 15, 27, 42,
   'Dessert', array['dessert', 'baking']::text[], null, 'Claude', array['Bake 25 to 30 minutes. Add 2 to 3 minutes if your oven runs cool or the pan is full to the top.', 'If you only have white sugar, use 1 1/2 cups white sugar plus 1 to 2 tablespoons molasses, honey or maple syrup for chew and caramel flavor. Without it they come out lighter and slightly crisper.', 'Walnuts work in place of pecans. They''re a bit more bitter, which is nice against the chocolate.', 'Keeps 3 to 4 days covered at room temperature, and freezes well wrapped in individual squares.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'crawfish-etouffee', 'Crawfish Étouffée', 'Crawfish tails in a smothered butter-roux sauce with onion, bell pepper and celery, served over rice.', 4, 15, 30, 45,
   'Seafood', array['seafood', 'cajun']::text[], null, 'https://www.explorelouisiana.com/culinary/recipes/crawfish-etouffee-recipe-and-instructional-video', array['Thaw frozen crawfish tails completely and drain off the liquid so it doesn''t thin the sauce.', 'Add Cajun seasoning gradually and taste before adding more.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'creamy-dill-cucumber-salad', 'Creamy Dill Cucumber Salad', 'A cool cucumber salad in a tangy sour cream and mayo dressing with plenty of dill and lemon.', 4, 15, 15, 30,
   'Salad', array['side', 'salad']::text[], null, 'Claude', array['Salting and draining the cucumbers is the key step. Skip it and the salad turns watery fast.', 'Sour cream makes this richer and less tangy than a yogurt version, but it works beautifully.', 'For extra silkiness, swap a spoonful of crème fraîche in for the mayo.', 'Best eaten within a day.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'creamy-razor-clam-chowder', 'Creamy Razor Clam Chowder', 'A creamy New England-style chowder made with razor clams, sized for a 3-quart pot.', 3, 15, 30, 45,
   'Soup', array['soup', 'seafood']::text[], null, 'Claude', array['Freeze clams flat in portion-size bags with any juice from shucking, and thaw overnight in the fridge.', 'For thicker chowder, mash a few potatoes against the side of the pot before adding the dairy.']::text[]),
  ('5b0c1f6e-3d7a-4c52-9e1b-0a6d2f8c4e17', 'lobster-mushroom-risotto', 'Lobster Mushroom Risotto', 'Creamy arborio risotto with diced lobster mushrooms, shallot, celery and sherry, finished with Parmesan and herbs.', 4, 15, 35, 50,
   'Pasta', array['mushroom', 'rice']::text[], null, 'https://langdoncook.com/2009/10/25/x-country-double-lobster-risotto/', array['The original recipe also adds cooked lobster meat at the end; the mushrooms are good on their own.', 'Dry white wine or dry vermouth can stand in for the sherry.', 'This makes a large pot. Halve everything for a smaller batch.']::text[]);

