insert into public.recipe_steps (recipe_id, position, title, text, timer_minutes)
select r.id, v.position, v.title::text, v.text, v.timer_minutes::integer
from (values
  ('avgolemono-lobster-mushroom-soup', 1, 'Sear the mushroom', 'Heat a wide pot over medium-high. Add the lobster mushroom with no fat and cook, stirring, until its liquid releases and cooks off. Add the olive oil and brown for another 3 minutes. Remove half to a plate for topping.', 8),
  ('avgolemono-lobster-mushroom-soup', 2, 'Soften the aromatics', 'Lower the heat to medium. Add the butter, onion and carrot and cook until soft but not browned. Stir in the garlic for 30 seconds.', 4),
  ('avgolemono-lobster-mushroom-soup', 3, 'Simmer the rice', 'Add the arborio rice and the warm stock. Bring to a boil, then reduce to a gentle simmer and cook until the rice is tender and the broth has some body, stirring occasionally.', null),
  ('avgolemono-lobster-mushroom-soup', 4, 'Temper the eggs', 'Take the pot off the heat and let it stop bubbling for a minute. Whisk the eggs in a bowl until frothy, then whisk in the lemon juice. Slowly ladle in about 1 cup of hot broth while whisking constantly so the eggs don''t scramble.', null),
  ('avgolemono-lobster-mushroom-soup', 5, 'Finish the soup', 'Stir the egg mixture back into the pot off the heat and stir for 2 minutes until silky and slightly thickened. Do not boil. Add the lemon zest, the dill or parsley, the salt and the black pepper, then taste and adjust the lemon and salt.', 2),
  ('avgolemono-lobster-mushroom-soup', 6, 'Serve', 'Ladle into bowls and top with the reserved seared mushroom, extra dill, black pepper and a drizzle of olive oil. Crusty bread is ideal.', null),
  ('chanterelle-cream-linguine', 1, 'Dry-sauté the chanterelles', 'Heat a large wide skillet over medium-high with no fat. Add the chanterelles in a single layer, working in batches if the pan is crowded, and cook until they release their liquid and it evaporates. Don''t salt yet.', null),
  ('chanterelle-cream-linguine', 2, 'Brown in butter', 'Add 1 tablespoon of the butter and the olive oil. Sauté until the mushrooms are golden at the edges, then scoop them into a bowl.', null),
  ('chanterelle-cream-linguine', 3, 'Start the pasta water', 'Meanwhile, boil a big pot of water with the kosher salt. Cook the linguine 1 minute short of the package time, then save a cup of pasta water before draining.', 10),
  ('chanterelle-cream-linguine', 4, 'Build the sauce base', 'Lower the skillet to medium and melt the remaining tablespoon of butter. Add the shallot and lemon zest and cook until soft, then add the garlic and thyme for 30 seconds.', 3),
  ('chanterelle-cream-linguine', 5, 'Deglaze and reduce', 'Pour in the white wine and scrape up the browned bits. Simmer until nearly gone, then stir in the heavy cream and simmer gently until slightly thickened.', null),
  ('chanterelle-cream-linguine', 6, 'Finish the pasta in the sauce', 'Add the drained linguine, the mushrooms, and the parmesan. Toss over low heat, adding pasta water a splash at a time until glossy and clingy. Season with the black pepper and taste before adding any salt, since the parmesan is salty. Top with the parsley.', null),
  ('chocolate-chip-pecan-blondies', 1, 'Prep pan and toast nuts', 'Heat the oven to 350°F. Line a 9x12x2 pan with parchment, leaving an overhang on two sides. Spread the pecans on a sheet pan and toast while the oven heats.', null),
  ('chocolate-chip-pecan-blondies', 2, 'Mix the wet ingredients', 'Whisk the melted butter and brown sugar until smooth. Whisk in the eggs and vanilla.', null),
  ('chocolate-chip-pecan-blondies', 3, 'Fold in dry ingredients', 'Add the flour, baking powder and salt and fold until just combined. Fold in the chocolate chips and the toasted pecans.', null),
  ('chocolate-chip-pecan-blondies', 4, 'Bake', 'Spread the batter evenly in the pan. Bake until the edges are set and golden and the center is just barely firm. A toothpick should come out with moist crumbs, not wet batter.', 27),
  ('chocolate-chip-pecan-blondies', 5, 'Cool completely', 'Cool in the pan, then lift out by the parchment and cut into squares. Cutting too early makes them gummy.', null),
  ('crawfish-etouffee', 1, 'Prep the vegetables', 'Chop the onion, bell pepper, celery, parsley and green onion, and mince the garlic, so everything is ready before the roux starts.', null),
  ('crawfish-etouffee', 2, 'Make the roux', 'Melt the butter in a large skillet over medium heat. Stir in the flour and cook, stirring constantly, until the roux turns a caramel color.', 4),
  ('crawfish-etouffee', 3, 'Cook the vegetables', 'Add the onion, bell pepper and celery and cook until tender. Add the garlic and cook for 1 more minute.', 4),
  ('crawfish-etouffee', 4, 'Add the stock', 'Slowly stir in the stock until the sauce is smooth. Season with the salt, black pepper and Cajun seasoning.', null),
  ('crawfish-etouffee', 5, 'Simmer', 'Bring to a boil, then reduce to medium-low, cover and simmer, stirring occasionally.', 15),
  ('crawfish-etouffee', 6, 'Add the crawfish', 'Stir in the crawfish tails and cook just until heated through. Stir in the parsley and green onion, saving a little of each for garnish.', 3),
  ('crawfish-etouffee', 7, 'Serve', 'Spoon over hot rice and garnish with the reserved parsley and green onion.', null),
  ('creamy-dill-cucumber-salad', 1, 'Slice and salt the cucumbers', 'Halve the English cucumbers lengthwise and slice thinly, about 1/8 inch, on a mandoline if you have one. Toss with 1 teaspoon kosher salt in a colander set over a bowl and let sit to draw out excess water.', null),
  ('creamy-dill-cucumber-salad', 2, 'Make the dressing', 'While the cucumbers drain, whisk together the sour cream, mayo, lemon juice, garlic and black pepper in a large bowl until smooth. Add the white wine vinegar if using.', null),
  ('creamy-dill-cucumber-salad', 3, 'Drain and dry the cucumbers', 'Press the cucumbers gently to release more liquid, then pat dry with a clean towel or paper towels. This keeps the salad from getting watery.', null),
  ('creamy-dill-cucumber-salad', 4, 'Combine', 'Add the cucumbers, dill, and red onion or shallot to the dressing. Toss gently to coat.', null),
  ('creamy-dill-cucumber-salad', 5, 'Chill and serve', 'Let the salad sit in the fridge for at least 15 minutes so the flavors meld before serving.', 15),
  ('creamy-razor-clam-chowder', 1, 'Render the bacon', 'Cook the bacon in the pot over medium heat until crisp. Remove it and set it aside, leaving the fat in the pot.', null),
  ('creamy-razor-clam-chowder', 2, 'Sauté the vegetables', 'Cook the onion and celery in the bacon fat until soft, about 5 minutes, adding the garlic for the last 30 seconds.', 5),
  ('creamy-razor-clam-chowder', 3, 'Make the roux', 'Sprinkle in the flour and stir constantly so it coats the vegetables and cooks out the raw flour taste.', null),
  ('creamy-razor-clam-chowder', 4, 'Add liquid and potatoes', 'Slowly whisk in the clam juice to avoid lumps. Add the potatoes, thyme and bay leaf, and simmer gently until the potatoes are tender.', null),
  ('creamy-razor-clam-chowder', 5, 'Add the dairy', 'Remove the thyme sprig and bay leaf. Stir in the cream and milk, and warm gently without letting it boil.', null),
  ('creamy-razor-clam-chowder', 6, 'Add the clams', 'Stir in the clams with their juice and cook just until opaque. Any longer and they turn rubbery.', null),
  ('creamy-razor-clam-chowder', 7, 'Season and serve', 'Taste first, since the clam juice is already salty. Add the black pepper and a splash of hot sauce or lemon if you like, then top with the crisp bacon.', null),
  ('lobster-mushroom-risotto', 1, 'Warm the stock', 'Heat the stock in a saucepan and keep it at a gentle simmer, not a boil, while you cook the rice.', null),
  ('lobster-mushroom-risotto', 2, 'Sauté the base', 'Melt the butter in a wide, heavy pot over medium-high heat. Cook the shallot, celery, garlic and mushrooms until the shallot turns translucent.', 5),
  ('lobster-mushroom-risotto', 3, 'Add the sherry and rice', 'Pour in the sherry and cook until most of the alcohol has evaporated. Stir in the rice to coat it in the butter and cook for a couple of minutes.', 3),
  ('lobster-mushroom-risotto', 4, 'Add the stock', 'Add the warm stock one ladleful at a time, stirring and letting each addition absorb before the next, until the rice is tender but still al dente and the risotto is creamy, not soupy.', 25),
  ('lobster-mushroom-risotto', 5, 'Finish and serve', 'Take the pot off the heat and stir in the Parmesan. Spoon into bowls and sprinkle with the parsley or chives.', null)
) as v (slug, position, title, text, timer_minutes)
join public.recipes r on r.slug = v.slug;
